"""Immutable observations and explicit diagnostics; no live score changes."""
from __future__ import annotations

import hashlib
import json
import math
import os
import tempfile
import uuid
import platform
import re
import shutil
from importlib import metadata
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from integrity import atomic_json, atomic_text

VERSION = 'evidence-v1'


def number(value):
    if isinstance(value, bool):
        return None
    try:
        value = float(value)
        return value if math.isfinite(value) else None
    except (TypeError, ValueError, OverflowError):
        return None


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False)


def digest(value):
    return hashlib.sha256(canonical(value).encode('utf-8')).hexdigest()


def model_bundle(root):
    """Archive executable source, not merely an unrecoverable hash."""
    sources = {p.name: p.read_text(encoding='utf-8')
               for p in sorted(Path(root).glob('*.py')) if not p.name.startswith('test_')}
    for p in sorted(Path(root).glob('requirements*.txt')):
        sources[p.name] = p.read_text(encoding='utf-8')
    for name in ('monitoring_status.json', 'source_reviews.json'):
        register = Path(root) / name
        if register.exists():
            sources[register.name] = register.read_text(encoding='utf-8')
    return {'sha256': digest(sources), 'sources': sources}


def runtime():
    packages = {}
    for package in ('yfinance', 'pandas', 'numpy'):
        try:
            packages[package] = metadata.version(package)
        except metadata.PackageNotFoundError:
            packages[package] = None
    return {'python': platform.python_version(), 'platform': platform.system(), 'packages': packages}


def business_quality(row, weights):
    """New diagnostic: g,p,c,b and dilution only, reweighted to 0..10.

    Excludes v, payout r and live valuation pr. Missing components are not
    filled from a published total. This is a declared heuristic, not calibrated.
    """
    sub = row.get('sub')
    if not sub or len(sub) != 6:
        return None
    values = {key: number(sub[i]) for key, i in [('g', 0), ('p', 1), ('c', 2), ('b', 3)]}
    values['d'] = number(row.get('dil'))
    if any(v is None or not 0 <= v <= 10 for v in values.values()):
        return None
    return sum(values[k] * weights[k] for k in values) / sum(weights[k] for k in values)


def valuation_contract(row):
    """Require a declared cash-flow basis; do not reinterpret legacy FCF."""
    basis = row.get('cash_flow_basis', 'UNSPECIFIED')
    # engine.rate_used() prioritizes r_wacc. A metadata declaration cannot turn
    # that actual WACC into cost of equity without changing the calculation.
    rate_basis = 'WACC' if row.get('r_wacc') else row.get('discount_rate_basis', 'UNSPECIFIED')
    expected = {'FCFE': 'COST_OF_EQUITY', 'FCFF': 'WACC'}.get(basis)
    missing = [k for k in ('financial_period', 'financial_published_at', 'cur', 'shares')
               if row.get(k) is None or row.get(k) == '']
    issues = []
    names = {'financial_period': 'financial period', 'financial_published_at': 'publication date',
             'cur': 'currency', 'shares': 'share count'}
    if missing:
        issues.append('Missing ' + ', '.join(names[k] for k in missing) + '.')
    if not expected:
        issues.append('Cash-flow definition and a matching discount-rate basis are not established.')
    elif rate_basis != expected:
        issues.append('Declared cash-flow and discount-rate bases disagree.')
    if not (row.get('shares_asof') or row.get('share_count_date')):
        issues.append('Share count needs a dated source and a corporate-action bridge.')
    if row.get('normalization_status') == 'REVIEW_REQUIRED' or row.get('built') in ('est', 'back-solved'):
        issues.append('Sustainable cash-flow normalization needs an explicit bridge from reported figures.')
    if basis == 'FCFF':
        issues.append('Legacy NGV does not subtract net debt; an FCFF equity bridge is required.')
    status = 'UNVERIFIED'
    if expected and rate_basis != expected:
        status = 'MISMATCH'
    elif expected and not missing and basis != 'FCFF':
        status = 'DECLARED'
    return {'status': status, 'cash_flow_basis': basis, 'discount_rate_basis': rate_basis,
            'missing': missing, 'legacy_formula': '(fcf / shares) / rate',
            'equity_bridge_required': basis == 'FCFF', 'issues': issues,
            'note': 'Legacy NGV is retained; a declared basis does not certify its inputs.'}


def declared_perpetuity(cash_flow, shares, rate, basis, rate_basis, net_debt=None):
    """Opt-in, separate valuation; never replaces engine.ngv()."""
    f, s, r = number(cash_flow), number(shares), number(rate)
    if f is None or s is None or s <= 0 or r is None or r <= 0:
        raise ValueError('Finite cash flow, positive shares and positive rate required')
    if basis == 'FCFE' and rate_basis == 'COST_OF_EQUITY':
        if net_debt is not None:
            raise ValueError('Do not subtract net debt from an equity cash-flow valuation')
        return f / r / s
    if basis == 'FCFF' and rate_basis == 'WACC' and number(net_debt) is not None:
        return (f / r - float(net_debt)) / s
    raise ValueError('Declare matching cash flow/rate bases and the FCFF net-debt bridge')


def growth_contract(row):
    """Metric type is explicit; revenue/volume/earnings are not cash-flow growth.

    CASH_FLOW describes the metric being compared, not source verification or
    a forecast. The existing mid-cycle producer exclusion remains in force.
    """
    basis = row.get('deliver_basis') or 'UNSPECIFIED'
    available = number(row.get('deliver')) is not None
    comparable = available and basis == 'CASH_FLOW' and not row.get('midcycle')
    return {'basis': basis, 'comparable': bool(comparable),
            'status': ('MISSING' if not available else
                       'COMPARABLE' if comparable else 'NOT_COMPARABLE'),
            'note': 'Cushion requires explicitly declared cash-flow growth; '
                    'production, revenue and other proxies do not enter the comparison.'}


def row_diagnostics(row, weights):
    sub = row.get('sub')
    complete = bool(sub and len(sub) == 6 and all(number(x) is not None for x in sub))
    px = number(row.get('price'))
    status = lambda value: 'AVAILABLE' if number(value) is not None else 'MISSING'
    return {'business_quality': business_quality(row, weights),
            'quality_version': 'g-p-c-b-d-renormalised-v1',
            'score_basis': 'LIVE_COMPOSITE' if complete else 'FIXED_TOTAL',
            'price': 'AVAILABLE' if px is not None and px > 0 else 'MISSING',
            'price_observed_at': row.get('quote_observed_at'),
            'fundamentals': 'COMPONENTS_PRESENT' if complete else 'INCOMPLETE',
            'ngv': 'NOT_APPLICABLE' if row.get('na') and not row.get('midcycle') else
                   ('INPUTS_PRESENT' if number(row.get('fcf')) is not None and
                    number(row.get('shares')) not in (None, 0) else 'MISSING'),
            'epv': status(row.get('epv_value')),
            'momentum': status(row.get('mom_12_1')),
            'regime_assumptions': [] if complete else ['balance=6', 'payout=6'],
            'valuation_contract': valuation_contract(row),
            'growth_contract': growth_contract(row)}


def create_record(rows, outputs, macro, models, source_hash, captured_at=None):
    captured_at = captured_at or datetime.now(timezone.utc).isoformat()
    stamp = datetime.fromisoformat(captured_at.replace('Z', '+00:00'))
    if stamp.tzinfo is None:
        raise ValueError('captured_at must include timezone')
    record = dict(outputs)
    record['_evidence'] = {'schema': VERSION, 'captured_at': stamp.astimezone(timezone.utc).isoformat(),
                           'inputs': rows, 'macro': macro, 'model_source_sha256': source_hash,
                           'universe_sha256': digest(sorted(rows)),
                           'runtime': runtime(),
                           'time_policy': 'Known from capture onward; older market history is reconstructed.'}
    record['_models'] = dict(models, evidence=VERSION)
    # Roundtrip also detaches mutable DATA and refuses non-JSON/non-finite values.
    return json.loads(canonical(record))


def immutable_json(path, value):
    """Publish a complete file atomically without replacing an existing file."""
    path = Path(path)
    payload = canonical(value) + '\n'
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix='.pending-', dir=path.parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(tmp, path)
        except FileExistsError:
            return False
        return True
    finally:
        os.unlink(tmp)


@contextmanager
def build_lock(root='history'):
    root = Path(root)
    root.mkdir(parents=True, exist_ok=True)
    lock = root / '_build.lock'
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except FileExistsError as exc:
        raise RuntimeError('Another build is active, or a crashed build left history/_build.lock') from exc
    try:
        with os.fdopen(fd, 'w') as stream:
            stream.write(str(os.getpid()))
        yield
    finally:
        lock.unlink()


def _validate_record_bundle(record, bundle):
    canonical(record)
    if bundle['sha256'] != digest(bundle['sources']):
        raise ValueError('Model bundle hash mismatch')
    if record['_evidence']['model_source_sha256'] != bundle['sha256']:
        raise ValueError('Observation/model bundle mismatch')
    stamp = datetime.fromisoformat(record['_evidence']['captured_at'])
    if stamp.tzinfo is None:
        raise ValueError('captured_at must include timezone')
    return stamp.astimezone(timezone.utc)


def publish_record(record, bundle, root='history'):
    """Standalone snapshot API; report builds use publish_build instead."""
    root = Path(root)
    stamp = _validate_record_bundle(record, bundle)
    day = stamp.astimezone(timezone.utc).date().isoformat()
    run_id = stamp.strftime('%Y%m%dT%H%M%S%f') + '-' + uuid.uuid4().hex
    model_path = root / 'models' / (bundle['sha256'] + '.json')
    if not immutable_json(model_path, bundle):
        if json.loads(model_path.read_text(encoding='utf-8')) != bundle:
            raise ValueError('Existing model archive is corrupt')
    if not immutable_json(root / 'runs' / (run_id + '.json'), record):
        raise FileExistsError(run_id)
    daily_created = immutable_json(root / (day + '.json'), record)
    return {'day': day, 'run_id': run_id, 'daily_created': daily_created}


def _load_build(root, run_id):
    if not isinstance(run_id, str) or not re.fullmatch(r'\d{8}T\d{12}-[0-9a-f]{32}', run_id):
        raise ValueError('Invalid build ID')
    folder = Path(root) / '_builds' / run_id
    manifest = json.loads((folder / 'manifest.json').read_text(encoding='utf-8'))
    if manifest.get('schema') != 'report-build-v1' or manifest.get('run_id') != run_id:
        raise ValueError('Invalid build manifest')
    record = json.loads((folder / 'observation.json').read_text(encoding='utf-8'))
    if digest(record) != manifest['observation_sha256']:
        raise ValueError('Build observation hash mismatch')
    report = folder / 'index.html'
    if hashlib.sha256(report.read_bytes()).hexdigest() != manifest['report_sha256']:
        raise ValueError('Build report hash mismatch')
    model_hash = manifest['model_source_sha256']
    if not re.fullmatch(r'[0-9a-f]{64}', model_hash):
        raise ValueError('Invalid model hash')
    bundle = json.loads((Path(root) / 'models' / (model_hash + '.json')).read_text(encoding='utf-8'))
    stamp = _validate_record_bundle(record, bundle)
    if bundle['sha256'] != model_hash or stamp.date().isoformat() != manifest['day']:
        raise ValueError('Build manifest does not match its observation/model')
    return {'manifest': manifest, 'record': record, 'report_path': report}


def current_build(root='history'):
    """Resolve one pointer once and verify its complete report/evidence pair.

    Deployments must use this report_path, never the compatibility index.html.
    """
    pointer = json.loads((Path(root) / '_current.json').read_text(encoding='utf-8'))
    build = _load_build(root, pointer['run_id'])
    if build['manifest'] != pointer:
        raise ValueError('Current build pointer/manifest mismatch')
    return build


def daily_records(root='history'):
    """First committed observation per UTC day, with legacy files preserved.

    Only builds reachable from _current.json count: a process killed before
    the pointer switch can leave staged/uncommitted files but no new evidence.
    """
    root = Path(root)
    days = {}
    for path in sorted(root.glob('????-??-??.json')):
        try:
            datetime.strptime(path.name, '%Y-%m-%d.json')
            value = json.loads(path.read_text(encoding='utf-8'))
            if isinstance(value, dict):
                days[path.stem] = value
        except (OSError, ValueError):
            continue
    if (root / '_current.json').exists():
        builds, seen = [], set()
        build = current_build(root)
        while True:
            manifest = build['manifest']
            if manifest['run_id'] in seen:
                raise ValueError('Cycle in committed build history')
            seen.add(manifest['run_id'])
            builds.append(build)
            previous = manifest.get('previous_run_id')
            if previous is None:
                break
            build = _load_build(root, previous)
        first = {}
        for build in reversed(builds):
            first.setdefault(build['manifest']['day'], build)
        for day, build in first.items():
            manifest = build['manifest']
            if manifest['daily_observation_sha256'] == manifest['observation_sha256']:
                # A failed mirror followed by a retry must not replace the first capture.
                days[day] = build['record']
            elif day not in days or digest(days[day]) != manifest['daily_observation_sha256']:
                raise ValueError(f'Legacy daily observation {day} is missing or corrupt')
    return sorted(days.items())


def publish_build(record, bundle, html, root='history', report_path='index.html'):
    """Commit a report and observation through one atomic pointer switch.

    Call under build_lock. Legacy day/run files and root index.html are
    compatibility mirrors written after commit; their failure cannot split
    the authoritative pair or feed uncommitted data to the forward harness.
    """
    stamp = _validate_record_bundle(record, bundle)
    root = Path(root)
    previous = current_build(root)['manifest'] if (root / '_current.json').exists() else None
    day = stamp.date().isoformat()
    prior_days = dict(daily_records(root))
    daily_created = day not in prior_days
    daily_record = prior_days.get(day, record)
    run_id = stamp.strftime('%Y%m%dT%H%M%S%f') + '-' + uuid.uuid4().hex
    manifest = {'schema': 'report-build-v1', 'run_id': run_id, 'day': day,
                'previous_run_id': previous['run_id'] if previous else None,
                'observation_sha256': digest(record),
                'daily_observation_sha256': digest(daily_record),
                'report_sha256': hashlib.sha256(html.encode('utf-8')).hexdigest(),
                'model_source_sha256': bundle['sha256']}
    model_path = root / 'models' / (bundle['sha256'] + '.json')
    if not immutable_json(model_path, bundle):
        if json.loads(model_path.read_text(encoding='utf-8')) != bundle:
            raise ValueError('Existing model archive is corrupt')
    builds = root / '_builds'
    builds.mkdir(parents=True, exist_ok=True)
    staged = Path(tempfile.mkdtemp(prefix='.pending-', dir=builds))
    destination = builds / run_id
    committed = False
    try:
        atomic_text(staged / 'index.html', html)
        atomic_text(staged / 'observation.json', canonical(record) + '\n')
        atomic_text(staged / 'manifest.json', canonical(manifest) + '\n')
        os.rename(staged, destination)
        atomic_json(root / '_current.json', manifest)
        committed = True
    finally:
        if staged.exists():
            shutil.rmtree(staged)
        if not committed and destination.exists():
            shutil.rmtree(destination)
    notes = []
    for path, value in ((root / 'runs' / (run_id + '.json'), record),
                        (root / (day + '.json'), daily_record)):
        try:
            immutable_json(path, value)
        except OSError as exc:
            notes.append(f'Compatibility archive {path} was not written: {exc}')
    try:
        atomic_text(report_path, html)
    except OSError as exc:
        notes.append(f'Compatibility report {report_path} was not written: {exc}; '
                     'use evidence.current_build() for the committed report')
    return {'day': day, 'run_id': run_id, 'daily_created': daily_created,
            'report_path': str(destination / 'index.html'), 'compatibility_warnings': notes}

sources.i18n.py:
"""Static, token-aware report localization; financial inputs are never re-evaluated.

localize accepts the canonical English report. The English edition changes only
language controls and their research links. translation_gaps inventories new
first-party UI text that needs catalog coverage; issuer/source prose is explicitly
labelled as original and excluded. Only stdlib modules are used.
"""
from __future__ import annotations

import base64
import json
import re
from functools import lru_cache
from html import escape, unescape
from html.parser import HTMLParser

from i18n_data import TRANSLATIONS

LANGUAGES = {'en': 'English', 'de': 'Deutsch', 'es': 'Español'}
LANGUAGE_NAV_ID = 'investorace-language-nav'
_VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
         'meta', 'param', 'source', 'track', 'wbr'}
_NOTICE = {
    'de': 'Originaltext: Quellenhinweise und Dokumenttitel bleiben in ihrer Originalsprache.',
    'es': 'Texto original: las notas de fuentes y los títulos de documentos conservan su idioma original.',
}
_NEUTRAL_WORDS = (
    'InvestorAce', 'Yahoo', 'Finance', 'yfinance', 'GitHub', 'NGV', 'EPV', 'FCF',
    'FCFE', 'FCFF', 'WACC', 'SMA', 'EMA', 'ATR', 'OHLC', 'TR', 'VIX', 'UTC', 'USD',
    'EUR', 'GBP', 'GBp', 'CAD', 'CHF', 'JPY', 'AUD', 'HKD', 'CNY', 'SEK',
    'NOK', 'DKK', 'REIT', 'S&P', 'SPY', '10Y', '6m', '10y', '1y', '3y',
    '5y', '12m', '9m', '3m', '1m', 'pp', 'bp', 'x', 'r', 't', 'n/a',
    'CLOCK', 'CONC', 'DIV', 'TTM', 'PROXY', 'CAGR', 'ARR', 'AFFO', 'DCF',
    'cRPO', 'FY26', 'FY25', 'YoY', 'cc', 'High', 'Low', 'Close', 'True', 'wacc',
)
_JS_PHRASES = {
    'Enter a Yahoo ticker first, e.g. ROAD or ASML.AS.',
    ' is already in the model.', 'Open GitHub issue for ',
    r'Opening GitHub...\n\nIf it does not open, use the green link below.\n\n',
    '  rank ', ' &middot; growth ', '% &middot; inflation ',
    'Auto-add ', 'Do not edit the title -- the workflow reads the ticker from it.',
    'It fetches price, shares and TTM free cash flow from Yahoo, drafts the',
    'mechanical fields and opens a tested draft PR for review.',
    '  deliver : revenue/operating proxies stay descriptive; a cushion requires',
    '            sourced cash-flow growth and deliver_basis=CASH_FLOW',
    'Negative free cash flow is written as na= with no NGV, by design.',
}
_JS_LITERAL = re.compile(r"""(?P<quote>['"])(?P<value>(?:\\.|(?!\1)[^\\])*?)(?P=quote)""", re.DOTALL)


def _language(language):
    if language not in LANGUAGES:
        raise ValueError('Unsupported language: ' + str(language))
    return language


def homepage(language='en'):
    """Root-relative static homepage, shared with research/market renderers."""
    _language(language)
    return 'index.html' if language == 'en' else 'index.' + language + '.html'


def _navigation(language):
    label = {'en': 'Language', 'de': 'Sprache', 'es': 'Idioma'}[language]
    links = ''.join(
        '<a href="' + homepage(code) + '" lang="' + code + '" hreflang="' + code + '"'
        + (' aria-current="page" style="color:inherit;font-weight:700;text-decoration:underline"'
           if code == language else ' style="color:inherit"')
        + '>' + name + '</a>' for code, name in LANGUAGES.items())
    return ('<nav id="' + LANGUAGE_NAV_ID + '" aria-label="' + label + '" '
            'style="display:flex;flex-wrap:wrap;gap:14px;align-items:center;margin:0 0 18px;'
            'padding:12px 16px;border:1px solid #2a3040;border-radius:10px;background:#141821">'
            '<span>' + label + ':</span>' + links + '</nav>')


@lru_cache(maxsize=2)
def _pattern(language):
    def term(key):
        return (r'(?<!\w)' if key[0].isalnum() else '') + re.escape(key) + (
            r'(?!\w)' if key[-1].isalnum() else '')
    return re.compile('|'.join(term(k) for k in sorted(TRANSLATIONS[language], key=len, reverse=True)))


def _residue(value):
    value = value.replace('auto_adjust=True daily High/Low/Close', '')
    value = re.sub(r'(?<=\d)(?:pp|bp|[ymx])\b', '', value)
    value = re.sub(r'\b[0-9a-f]{32,64}\b', '', value)
    value = re.sub(r'\b\d{4}-\d{2}-\d{2}(?:T[\d:.]+(?:Z|[+-]\d{2}:\d{2}))?', '', value)
    value = re.sub(r'\b[a-z][a-z0-9.-]*-v\d+(?:[.-][a-z0-9-]+)*\b', '', value)
    value = re.sub(r'\bv\d+(?:[.-][a-z0-9-]+)*\b', '', value)
    value = re.sub(r'\b[A-Za-z_+-]+/[A-Za-z_+-]+\b', '', value)
    value = re.sub(r'\b(?:ISSUER_[A-Z_]+|SELECTED_NORMALIZED_ASSUMPTION|OCF_MINUS_CAPEX|COST_OF_EQUITY)\b', '', value)
    value = re.sub(r'\b[A-Z]\w*(?:Error|Exception)\b', '', value)
    value = value.replace('auto_adjust=True daily High/Low/Close', '').replace('history/', '')
    value = re.sub('|'.join(r'(?<!\w)' + re.escape(w) + r'(?!\w)' for w in sorted(_NEUTRAL_WORDS, key=len, reverse=True)), '', value)
    return re.sub(r'[\d\s\W_]+', '', value)


def _translate(value, language):
    """Translate known UI spans once and report any remaining prose."""
    if language == 'en' or not value.strip():
        return value, ''
    catalog = TRANSLATIONS[language]
    normalized = re.sub(r'\s+', ' ', value.strip())
    pattern = _pattern(language)
    translated = pattern.sub(lambda m: catalog[m.group()], normalized)
    missing = _residue(pattern.sub('', normalized))
    leading = value[:len(value) - len(value.lstrip())]
    trailing = value[len(value.rstrip()):]
    return leading + translated + trailing, missing


def _attribute(raw, name, value):
    pattern = re.compile(r'(\s' + re.escape(name) + r'\s*=\s*)(["\'])(.*?)\2', re.I | re.S)
    if pattern.search(raw):
        return pattern.sub(lambda m: m.group(1) + m.group(2) + escape(value, quote=True) + m.group(2),
                           raw, count=1)
    # Only controlled accessibility/lang attributes are added through this path.
    return re.sub(r'(\s*/?>)$', lambda m: ' ' + name + '="' + escape(value, quote=True) + '"' + m.group(1), raw, count=1)


class _Report(HTMLParser):
    def __init__(self, language, navigation=True):
        super().__init__(convert_charrefs=False)
        self.language = language
        self.navigation = navigation
        self.parts = []
        self.stack = []
        self.pending = []
        self.skip_navigation = 0
        self.gaps = set()

    def _notice(self):
        return '<small class="source-original">' + escape(_NOTICE[self.language]) + '</small>'

    def _research(self):
        return any(f['attrs'].get('id') == 'investorace-research-nav' for f in self.stack)

    def _source_scope(self):
        return any(f['source'] for f in self.stack)

    def _ticker(self, text):
        if not self.stack:
            return False
        current = self.stack[-1]
        if current['tag'] == 'td' and (
                'tk' in current['attrs'].get('class', '').split() or current.get('ticker')):
            return text not in {'score', 'cover', 'cushion', 'momentum'}
        return (current['tag'] == 'b' and len(self.stack) > 1
                and self.stack[-2]['tag'] == 'summary'
                and any('decision-stock' in f['attrs'].get('class', '').split() for f in self.stack))

    def _flush(self):
        if not self.pending:
            return
        raw = ''.join(self.pending)
        self.pending = []
        if self.skip_navigation:
            return
        value = unescape(raw)
        if not self.stack:
            self.parts.append(raw)
            return
        current = self.stack[-1]
        tag = current['tag']
        if tag == 'style':
            self.parts.append(raw)
            return
        if tag == 'script':
            self.parts.append(self._script(raw) if self.language != 'en' else raw)
            return
        for frame in self.stack:
            if frame['tag'] == 'th':
                frame['text'] += value
        if tag == 'h2' and value.strip().startswith('Price issues this run'):
            for frame in reversed(self.stack[:-1]):
                if frame['tag'] == 'div':
                    frame['original_records'] = True
                    break
        if self.language == 'en':
            # Legacy research controls contained a German default market label.
            if self._research():
                raw = raw.replace('Montagsbriefing', 'Monday briefing')
            self.parts.append(raw)
            return
        if self._ticker(value.strip()):
            self.parts.append(raw)
            return
        if 'decision-alert' in current['attrs'].get('class', '').split():
            # Translate the event, never the symbol between the two separators.
            fields = value.split(' · ')
            if len(fields) >= 3:
                fields[0] = _translate(fields[0], self.language)[0]
                self.parts.append(escape(' · '.join(fields), quote=False))
                return
        # These prose fields contain symbols as data. Translate their labels
        # and explanations, while leaving the symbols outside the catalog.
        ticker_label = 'Held positions missing quotes:'
        if value.lstrip().startswith(ticker_label):
            start = raw.index(ticker_label)
            self.parts.append(raw[:start] + escape(TRANSLATIONS[self.language][ticker_label], quote=False)
                              + raw[start + len(ticker_label):])
            return
        fallback_label = 'Manual discount-rate fallbacks:'
        if value.lstrip().startswith(fallback_label):
            prefix, tail = value.split(fallback_label, 1)
            def fallback(match):
                note, missing = _translate(match.group(4), self.language)
                if missing:
                    self.gaps.add(match.group(4))
                return match.group(1) + match.group(2) + match.group(3) + note
            tail = re.sub(r'(^|;\s*)([A-Za-z0-9.^=_-]+)(:\s*)([^;]*)', fallback, tail)
            self.parts.append(escape(prefix + TRANSLATIONS[self.language][fallback_label] + tail,
                                     quote=False))
            return
        if self._source_scope():
            if tag in {'summary', 'b'}:
                fields = value.rsplit(' · ', 1)
                if len(fields) == 2:
                    fields[-1] = _translate(fields[-1], self.language)[0]
                    self.parts.append(escape(' · '.join(fields), quote=False))
                    return
            # Source reasons, limitations, disclosed security types, issuer
            # titles and transaction notes must remain verbatim. UI labels
            # remain translated; the containing record has an original notice.
            if tag not in {'b', 'th'}:
                core = value.strip()
                table = current.get('table')
                category = (tag == 'td' and table
                            and current['column'] < len(table['headers'])
                            and table['headers'][current['column']] == 'Disclosed type')
                if category:
                    label, separator, code = value.rpartition(' [')
                    if separator:
                        label, missing = _translate(label, self.language)
                        if missing:
                            self.gaps.add(value.strip())
                        self.parts.append(escape(label + separator + code, quote=False))
                        return
                is_ui = (category or core in {
                    'No transactions reported in the checked public register for this window.',
                    'Filing', 'checked', '· checked'}
                    or core.startswith(('Primary source ', '10b5-1:')))
                if core.startswith('Next review:'):
                    translated = TRANSLATIONS[self.language]['Next review:']
                    self.parts.append(escape(translated, quote=False) + raw[raw.index('Next review:') + len('Next review:'):])
                    return
                if not is_ui:
                    self.parts.append(raw)
                    return
        if any(f.get('original_records') for f in self.stack) and tag != 'h2':
            self.parts.append(raw)
            return
        if tag == 'a' and current['attrs'].get('href', '').startswith(('https://', 'http://')):
            core = value.strip()
            if core not in {'How stop orders work', 'Filing'} and not core.startswith('Primary source '):
                self.parts.append(raw)
                return
        # The detail includes a user-authored growth-metric description. Keep
        # this descriptor original; translate the surrounding first-party rule.
        metric = re.match(r'([+-]?\d[\d.,]*%\s+)(.*?)(; basis:.*)', value, re.S)
        if metric and any('review-note' in f['attrs'].get('class', '').split() for f in self.stack):
            prefix, descriptor, suffix = metric.groups()
            translated_descriptor, missing = _translate(descriptor, self.language)
            if missing:
                translated_descriptor = ('[' + {'de': 'Originaltext', 'es': 'Texto original'}[self.language]
                                         + ': ' + descriptor + ']')
            suffix = _translate(suffix, self.language)[0]
            self.parts.append(escape(prefix + translated_descriptor + suffix, quote=False))
            return
        # Source-attached quote warnings have no stable wording; mark them.
        if tag in {'span', 'div'} and '#f06a6a' in current['attrs'].get('style', ''):
            candidate, missing = _translate(value, self.language)
            if missing:
                self.parts.append(self._notice() + raw)
                return
        translated, missing = _translate(value, self.language)
        if missing and re.search(r'[A-Za-z]{2}', missing):
            self.gaps.add(re.sub(r'\s+', ' ', value.strip()))
        self.parts.append(raw if translated == value else escape(translated, quote=False))

    def _script(self, script):
        def portfolio(match):
            try:
                decoded = base64.b64decode(match.group(3), validate=True).decode('utf-8')
            except (ValueError, UnicodeError):
                return match.group()
            parser = _Report(self.language, navigation=False)
            parser.feed(decoded)
            parser.close()
            self.gaps.update(parser.gaps)
            encoded = base64.b64encode(parser.result().encode('utf-8')).decode('ascii')
            return match.group(1) + match.group(2) + encoded + match.group(2)
        script = re.sub(r'(\bconst\s+ZP\s*=\s*)(["\'])([A-Za-z0-9+/=]+)\2', portfolio, script)
        catalog = TRANSLATIONS[self.language]

        def literal(match):
            value = match.group('value')
            before = script[max(0, match.start()-220):match.start()]
            ui = (re.search(r'(?:\blabel|\btext)\s*:\s*$|\bfillText\(\s*$', before)
                  or re.search(r'(?:out\.value|link\.textContent|n\.textContent)\s*=[^;{}\n]*$', before)
                  or value in _JS_PHRASES)
            if not ui:
                return match.group()
            if value in catalog:
                translated = catalog[value]
                # Catalog JS messages store escaped line breaks intentionally.
                translated = translated.replace(r'\n', '\n')
                return json.dumps(translated, ensure_ascii=False)
            if _residue(value) and value not in {'', ' ', '%', ' \\u2192'}:
                self.gaps.add('JavaScript UI: ' + value)
            return match.group()
        script = _JS_LITERAL.sub(literal, script)
        # Map display values at the tooltip, keeping QT/QH and regime-series
        # keys and their entire JSON payloads byte-for-byte intact.
        tooltip = re.compile(r"(c\.raw\.y\.toFixed\(1\)\s*\+\s*['\"]% &middot; ['\"]\s*\+\s*)c\.raw\.q")
        script, count = tooltip.subn(lambda m: m.group(1) + '_iaLabel(c.raw.q)', script)
        if count:
            script = script.replace("c.raw.l + ", "_iaLabel(c.raw.l) + ")
            labels = {k: catalog.get(k, k) for k in (
                'GOLDILOCKS', 'REFLATION', 'INFLATION', 'STAGFLATION', 'RECESSION')}
            labels['now'] = {'de': 'jetzt', 'es': 'ahora'}[self.language]
            script = ('const _IA_LABELS=' + json.dumps(labels, ensure_ascii=False)
                      + ';\nfunction _iaLabel(v){return _IA_LABELS[v] || v;}\n' + script)
        return script

    def handle_starttag(self, tag, attrs):
        self._flush()
        attrs = dict(attrs)
        if self.skip_navigation:
            if tag == 'nav':
                self.skip_navigation += 1
            return
        if tag == 'nav' and attrs.get('id') == LANGUAGE_NAV_ID:
            self.skip_navigation = 1
            return
        raw = self.get_starttag_text()
        if tag == 'html':
            raw = _attribute(raw, 'lang', self.language)
        if tag == 'a' and self._research():
            match = re.fullmatch(r'(market|research)(?:-(?:en|de|es))?\.html', attrs.get('href', ''))
            if match:
                series = match.group(1)
                suffix = '' if series == 'research' and self.language == 'en' else '-' + self.language
                raw = _attribute(raw, 'href', series + suffix + '.html')
        if self.language != 'en':
            for key in ('title', 'placeholder', 'aria-label', 'alt'):
                if key in attrs and attrs[key]:
                    value = attrs[key]
                    if key == 'title' and value.startswith('Filing coverage') and ': ' in value:
                        prefix, note = value.split(': ', 1)
                        value = _translate(prefix, self.language)[0] + ' · ' + {
                            'de': 'Originaltext: ', 'es': 'Texto original: '}[self.language] + note
                    else:
                        value, _ = _translate(value, self.language)
                    if value != attrs[key]:
                        raw = _attribute(raw, key, value)
            if attrs.get('id') in {'zielIn', 'zielBtn'}:
                labels = {'de': ('Portfolio-Zugangswort', 'Portfolio öffnen'),
                          'es': ('Clave de acceso a la cartera', 'Abrir cartera')}
                raw = _attribute(raw, 'aria-label', labels[self.language][attrs['id'] == 'zielBtn'])
        self.parts.append(raw)
        if tag == 'body' and self.navigation:
            self.parts.append(_navigation(self.language))
        frame = {'tag': tag, 'attrs': attrs, 'text': '', 'source': (
            attrs.get('id', '').startswith(('review-', 'filing-')))}
        if tag == 'table':
            frame.update(headers=[], column=0)
        table = next((f for f in reversed(self.stack) if f['tag'] == 'table'), None)
        if table and tag == 'tr':
            table['column'] = 0
        if table and tag in {'td', 'th'}:
            index = table['column']
            table['column'] += 1
            frame['column'] = index
            frame['table'] = table
            frame['ticker'] = (tag == 'td' and index < len(table['headers'])
                               and table['headers'][index] == 'Ticker')
        if tag not in _VOID:
            self.stack.append(frame)
        if frame['source'] and tag != 'details' and self.language != 'en':
            self.parts.append(self._notice())

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in _VOID:
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        self._flush()
        if self.skip_navigation:
            if tag == 'nav':
                self.skip_navigation -= 1
            return
        found = next((i for i in range(len(self.stack)-1, -1, -1)
                      if self.stack[i]['tag'] == tag), None)
        frame = self.stack[found] if found is not None else None
        if frame and tag == 'th':
            headers = frame['table']['headers']
            while len(headers) <= frame['column']:
                headers.append('')
            headers[frame['column']] = frame['text'].strip()
        self.parts.append('</' + tag + '>')
        if self.language != 'en' and tag == 'summary' and self._source_scope():
            self.parts.append(self._notice())
        if self.language != 'en' and tag == 'h2' and any(f.get('original_records') for f in self.stack):
            self.parts.append(self._notice())
        if found is not None:
            del self.stack[found:]

    def handle_data(self, data):
        self.pending.append(data)

    def handle_entityref(self, name):
        self.pending.append('&' + name + ';')

    def handle_charref(self, name):
        self.pending.append('&#' + name + ';')

    def handle_comment(self, data):
        self._flush()
        if not self.skip_navigation:
            self.parts.append('<!--' + data + '-->')

    def handle_decl(self, decl):
        self._flush()
        self.parts.append('<!' + decl + '>')

    def handle_pi(self, data):
        self._flush()
        self.parts.append('<?' + data + '>')

    def close(self):
        super().close()
        self._flush()

    def result(self):
        return ''.join(self.parts)


def localize(html: str, language='en') -> str:
    """Create one static edition from canonical English; never mutate model data."""
    _language(language)
    parser = _Report(language)
    parser.feed(html)
    parser.close()
    return parser.result()


def translation_gaps(html: str) -> list[str]:
    """Inventory unmatched English UI prose (including the hidden portfolio).

    This deliberately ignores labelled source records, original issuer document
    titles, ticker cells and opaque provenance identifiers. New first-party UI
    sentences are reported so coverage tests fail when the catalog needs updating.
    """
    parser = _Report('de', navigation=False)
    parser.feed(html)
    parser.close()
    return sorted(parser.gaps)

